#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s file\n", argv[0]); return 1; }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc(sz);
    fread(buf, 1, sz, f);
    fclose(f);
    LLVMFuzzerTestOneInput(buf, sz);
    free(buf);
    return 0;
}
EOF
gcc -g -O0 -fsanitize=address -I./include -I./ /tmp/main.c /workspace/repo-vul/src-vul/fuzz_parse.c -o /tmp/fuzz_parse ./bin/gcc/libgpac_static.a -lm -lz -llzma -lopenjp2 -lpthread -DGPAC_HAVE_CONFIG_H 2>&1 | tail -20; echo "exit: ${PIPESTATUS[0]}"

